76	    /**
77	     * Monotonically increasing sequence for the structured OWNER_CREATED audit events, incremented
78	     * once per successful create so every emitted event carries a strictly greater {@code seq} than
79	     * the one before it.
80	     */
81	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
82	        new java.util.concurrent.atomic.AtomicLong();
