92	     * Remembers, per idempotency key, the id of the owner created by the first request that carried
93	     * that key, so a repeat with the same key resolves back to the original owner instead of
94	     * creating a duplicate.
95	     */
96	    private final java.util.Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
97	
