150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
154	        // owner originally created for that key with 200, instead of creating a duplicate.
155	        String idempotencyKey = currentIdempotencyKey();
156	        if (idempotencyKey != null) {
157	            Integer existingId = idempotentCreates.get(idempotencyKey);
158	            if (existingId != null) {
159	                Owner existing = this.clinicService.findOwnerById(existingId);
160	                if (existing != null) {
161	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
162	                    existingDto.setBulkSignupWarning(isBulkSignupWarning());
163	                    existingDto.setCapacityWarning(isCityApproachingCapacity(existing.getCity()));
164	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
165	                }
166	            }
167	        }
168	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
169	        // for backward compatibility. When structured, the stored/returned address is the composed
170	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
171	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
172	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
173	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
174	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
175	        String address;
176	        if (structured) {
177	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
178	        } else {
179	            address = normalizeAddress(ownerFieldsDto.getAddress());
180	        }
181	        List<String> missingFields = new ArrayList<>();
182	        if (isBlank(ownerFieldsDto.getFirstName())) {
183	            missingFields.add("firstName");
184	        }
185	        if (isBlank(ownerFieldsDto.getLastName())) {
186	            missingFields.add("lastName");
187	        }
188	        if (isBlank(address)) {
189	            missingFields.add("address");
190	        }
191	        if (isBlank(ownerFieldsDto.getCity())) {
192	            missingFields.add("city");
193	        }
194	        if (isBlank(ownerFieldsDto.getTelephone())) {
195	            missingFields.add("telephone");
196	        }
197	        if (!missingFields.isEmpty()) {
198	            throw new MissingOwnerFieldsException(missingFields);
199	        }
200	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
201	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
202	        HttpHeaders headers = new HttpHeaders();
203	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
204	        owner.setAddress(address);
205	        owner.setAddressLine1(structured ? addressLine1 : null);
206	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
207	        owner.setTelephone(telephone);
208	        validateEmailDomain(owner.getEmail());
209	        validatePostcode(owner.getPostcode(), owner.getRegion());
210	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
211	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
212	        // explicit link. This computed value drives duplicate detection and the household size.
213	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
214	        // A new owner may join an existing household (same computed householdId); rather than being
215	        // rejected, the joiner is admitted with a capped membership level (see below). The householdId
216	        // no longer feeds duplicate detection.
217	        // Duplicate detection is consolidated into the single derived identity key (telephone, email
218	        // and the last name's Soundex): a create is rejected when the new owner's whole identity key
219	        // equals an existing owner's.
220	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
221	            throw new DuplicateIdentityException(owner.getIdentityKey());
222	        }
223	        if (isCityAtCapacity(owner.getCity())) {
224	            throw new CityAtCapacityException(owner.getCity());
225	        }
226	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
227	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
228	        }
229	        LocalDate effectiveDate = owner.getRegistrationDate() != null
230	            ? owner.getRegistrationDate() : LocalDate.now();
231	        LocalDate registrationDate = toBusinessDay(effectiveDate);
232	        if (isDailyRegistrationLimitReached(registrationDate)) {
233	            throw new DailyRegistrationLimitException(registrationDate);
234	        }
235	        owner.setRegistrationDate(registrationDate);
236	        owner.setMemberId(deduplicateMemberId(memberIdFor(owner)));
237	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
238	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
239	        owner.setMembershipLevel(cappedMembershipLevel(owner));
240	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
241	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
242	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
243	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
244	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
245	        this.clinicService.saveOwner(owner);
246	        if (idempotencyKey != null) {
247	            idempotentCreates.put(idempotencyKey, owner.getId());
248	        }
249	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
250	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
251	        AUDIT.info(ownerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner));
252	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
253	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
254	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
255	        ownerDto.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
256	        headers.setLocation(UriComponentsBuilder.newInstance()
257	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
258	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
259	    }
