360	    private static boolean isBlank(String value) {
361	        return value == null || value.isBlank();
362	    }
363	
364	    /**
365	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
366	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
367	     *
368	     * @return the trimmed idempotency key, or {@code null} when none was supplied
369	     */
370	    private static String currentIdempotencyKey() {
371	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
372	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
373	            return null;
374	        }
375	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
376	        return isBlank(key) ? null : key.trim();
377	    }
