379	    /**
380	     * The set of disposable email domains that owners may not register with. Compared
381	     * case-insensitively against the domain part of the supplied email.
382	     */
383	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
384	        "mailinator.com", "tempmail.com", "guerrillamail.com");
385	
386	    /**
387	     * Rejects an owner whose email domain is on the disposable-domain blocklist
388	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
389	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
390	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
391	     * case-insensitively; the stored email is already lower-cased.
392	     *
393	     * @param email the owner's email (may be {@code null})
394	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
395	     */
396	    private static void validateEmailDomain(String email) {
397	        if (isBlank(email)) {
398	            return;
399	        }
400	        int at = email.lastIndexOf('@');
401	        if (at < 0) {
402	            return;
403	        }
404	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
405	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
406	            throw new DisposableEmailDomainException(email);
407	        }
408	    }
409	
410	    /**
411	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
412	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
413	     */
414	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
415	        "NSW", new int[] {2000, 2099},
416	        "VIC", new int[] {3000, 3099},
417	        "QLD", new int[] {4000, 4099});
418	
419	    /**
420	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
421	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
422	     * present, the value has already passed the 4-digit format check (Bean Validation on the
423	     * request body); this enforces that it falls within the inclusive range for the city's region
424	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
425	     *
426	     * @param postcode the supplied postcode (may be {@code null})
427	     * @param region the owner's locality/region derived from its city
428	     * @throws InvalidPostcodeException if the postcode is out of range for the region
429	     */
430	    private static void validatePostcode(String postcode, String region) {
431	        if (isBlank(postcode)) {
432	            return;
433	        }
434	        int[] range = REGION_POSTCODES.get(region);
435	        if (range == null) {
436	            return;
437	        }
438	        int value;
439	        try {
440	            value = Integer.parseInt(postcode);
441	        }
442	        catch (NumberFormatException e) {
443	            throw new InvalidPostcodeException(postcode);
444	        }
445	        if (value < range[0] || value > range[1]) {
446	            throw new InvalidPostcodeException(postcode);
447	        }
448	    }
