450	    /**
451	     * Normalizes a street address into the canonical form stored on and returned for a newly
452	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
453	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
454	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
455	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
456	     * value is what gets persisted, echoed back, and used for every address comparison (household
457	     * duplicate detection and the shared household identifier).
458	     *
459	     * @param rawAddress the address value as supplied by the client
460	     * @return the normalized address (possibly empty, never {@code null})
461	     */
462	    private static String normalizeAddress(String rawAddress) {
463	        if (rawAddress == null) {
464	            return "";
465	        }
466	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
467	        if (collapsed.isEmpty()) {
468	            return "";
469	        }
470	        String[] tokens = collapsed.split(" ");
471	        StringBuilder sb = new StringBuilder(collapsed.length());
472	        for (int i = 0; i < tokens.length; i++) {
473	            String token = tokens[i];
474	            switch (token) {
475	                case "ST" -> token = "STREET";
476	                case "RD" -> token = "ROAD";
477	                case "AVE" -> token = "AVENUE";
478	                default -> { }
479	            }
480	            if (i > 0) {
481	                sb.append(' ');
482	            }
483	            sb.append(token);
484	        }
485	        return sb.toString();
486	    }
