488	    /** The month on which the fiscal year starts: 1 July. */
489	    private static final java.time.Month FISCAL_YEAR_START_MONTH = java.time.Month.JULY;
490	
491	    /**
492	     * The calendar year in which the fiscal year containing {@code date} began. The fiscal year
493	     * starts on 1 July, so a date in July through December belongs to a fiscal year that began in
494	     * its own calendar year, while a date in January through June belongs to one that began in the
495	     * previous calendar year.
496	     */
497	    private static int fiscalYearStart(LocalDate date) {
498	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
499	    }
