501	    /**
502	     * Builds the member id assigned to a newly created owner, formatted
503	     * {@code <REGION><FY><HASH8><CHK>}: {@code REGION} is the region derived from the owner's
504	     * postcode (see {@link Owner#getRegion()}); {@code FY} is the two-digit fiscal year of the
505	     * (business-day-adjusted) {@code registrationDate} (the fiscal year starts on 1 July);
506	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
507	     * normalized (E.164) telephone concatenated with its last name; and {@code CHK} is a single Luhn
508	     * check digit computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D5}).
509	     * No sequence number is involved, so the id depends only on the owner's own region, fiscal year
510	     * and identity.
511	     *
512	     * @param owner the owner being created, with telephone normalized and registrationDate/postcode set
513	     * @return the member id to assign
514	     */
515	    private static String memberIdFor(Owner owner) {
516	        String fiscalYear = String.format("%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
517	        String base = owner.getRegion() + fiscalYear
518	            + telephoneNameHash(owner.getTelephone(), owner.getLastName());
519	        return base + luhnCheckDigit(base);
520	    }
521	
522	    /**
523	     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
524	     * characters are ignored; the standard Luhn algorithm doubles every second digit from the right
525	     * (subtracting 9 when the result exceeds 9) and the check digit is {@code (10 - (sum % 10)) % 10}.
526	     *
527	     * @param value the string whose contained digits are checked
528	     * @return the Luhn check digit
529	     */
530	    private static int luhnCheckDigit(String value) {
531	        int sum = 0;
532	        boolean dbl = true;
533	        for (int i = value.length() - 1; i >= 0; i--) {
534	            char c = value.charAt(i);
535	            if (c < '0' || c > '9') {
536	                continue;
537	            }
538	            int d = c - '0';
539	            if (dbl) {
540	                d *= 2;
541	                if (d > 9) {
542	                    d -= 9;
543	                }
544	            }
545	            sum += d;
546	            dbl = !dbl;
547	        }
548	        return (10 - (sum % 10)) % 10;
549	    }
