563	     * Renders the immutable structured {@code OWNER_CREATED} audit event as a compact JSON object
564	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. The {@code memberId}
565	     * field carries the owner's current {@link #primaryIdentifier(Owner) primary identifier}. All
566	     * values are numeric or a code drawn from {@code [A-Z0-9-]}, so no JSON escaping is required.
567	     *
568	     * @param seq   the monotonically increasing event sequence for this create
569	     * @param owner the owner just created
570	     * @return the event serialized as a JSON string
571	     */
572	    private static String ownerCreatedEvent(long seq, Owner owner) {
573	        return String.format(
574	            "{\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
575	            seq, owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
