578	    /**
579	     * De-duplicates a freshly computed member id against the ids already assigned to existing
580	     * owners. When no existing owner carries the given id it is returned unchanged; otherwise the
581	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields an id no existing owner holds is
582	     * appended, guaranteeing distinct owners always receive distinct member ids.
583	     *
584	     * @param memberId the member id computed for the owner being created
585	     * @return the de-duplicated member id, unique among existing owners
586	     */
587	    private String deduplicateMemberId(String memberId) {
588	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
589	            .map(Owner::getMemberId)
590	            .filter(java.util.Objects::nonNull)
591	            .collect(java.util.stream.Collectors.toSet());
592	        if (!existing.contains(memberId)) {
593	            return memberId;
594	        }
595	        int n = 2;
596	        while (existing.contains(memberId + "-" + n)) {
597	            n++;
598	        }
599	        return memberId + "-" + n;
600	    }
