602	    /**
603	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
604	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
605	     * last name.
606	     *
607	     * @param normalizedTelephone the owner's telephone in E.164 form
608	     * @param lastName the owner's last name
609	     * @return the 8-character upper-case hex hash
610	     */
611	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
612	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
613	            + (lastName == null ? "" : lastName);
614	        try {
615	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
616	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
617	            StringBuilder sb = new StringBuilder(digest.length * 2);
618	            for (byte b : digest) {
619	                sb.append(String.format("%02x", b));
620	            }
621	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
622	        }
623	        catch (java.security.NoSuchAlgorithmException e) {
624	            throw new IllegalStateException("SHA-256 not available", e);
625	        }
626	    }
