628	    /**
629	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
630	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
631	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
632	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
633	     * the national number must match the country code: {@code +61} requires 9 national digits and
634	     * {@code +1} requires 10.
635	     *
636	     * @param rawTelephone the telephone value as supplied by the client
637	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
638	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
639	     */
640	    private static String normalizeTelephone(String rawTelephone) {
641	        if (rawTelephone == null) {
642	            throw new InvalidTelephoneException(rawTelephone);
643	        }
644	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
645	        String e164;
646	        if (cleaned.startsWith("+")) {
647	            String digits = cleaned.substring(1);
648	            if (!digits.matches("[0-9]+")) {
649	                throw new InvalidTelephoneException(rawTelephone);
650	            }
651	            e164 = "+" + digits;
652	        } else {
653	            if (!cleaned.matches("[0-9]+")) {
654	                throw new InvalidTelephoneException(rawTelephone);
655	            }
656	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
657	            e164 = "+61" + national;
658	        }
659	        int digitCount = e164.length() - 1;
660	        if (digitCount < 8 || digitCount > 15) {
661	            throw new InvalidTelephoneException(rawTelephone);
662	        }
663	        if (e164.startsWith("+61")) {
664	            if (e164.length() - "+61".length() != 9) {
665	                throw new InvalidTelephoneException(rawTelephone);
666	            }
667	        }
668	        else if (e164.startsWith("+1")) {
669	            if (e164.length() - "+1".length() != 10) {
670	                throw new InvalidTelephoneException(rawTelephone);
671	            }
672	        }
673	        return e164;
674	    }
