676	    /**
677	     * Determines whether any existing (non-deleted) owner already carries the given identity key. The
678	     * identity key (the SHA-256 hex over {@code normalizedTelephone + '|' + lowerEmail + '|' +
679	     * soundex(lastName)}) is the single value all duplicate detection is based on, so two owners
680	     * collide only when their whole identity keys are equal.
681	     *
682	     * @param identityKey the identity key of the owner being created
683	     * @return {@code true} if another owner already has the same identity key
684	     */
685	    private boolean isIdentityKeyInUse(String identityKey) {
686	        return this.clinicService.findAllOwners().stream()
687	            .filter(existing -> !existing.isDeleted())
688	            .map(Owner::getIdentityKey)
689	            .anyMatch(identityKey::equals);
690	    }
