692	    /**
693	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
694	     * whose last name has the same Soundex code and whose postcode matches, but whose whole identity
695	     * key <em>differs</em> (so it is not a hard duplicate). Because the telephone is part of the
696	     * identity key, two owners sharing a last name (by Soundex) and postcode but carrying different
697	     * telephones fall here rather than being rejected. Such a create is not rejected, but is flagged.
698	     * An owner with no postcode can never be a soft duplicate. When several owners match, the earliest
699	     * (lowest id) is returned so the result is deterministic.
700	     *
701	     * @param owner the owner being created (telephone already normalized, postcode set)
702	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
703	     */
704	    private Integer possibleDuplicateOf(Owner owner) {
705	        if (isBlank(owner.getPostcode())) {
706	            return null;
707	        }
708	        String lastNameSoundex = Owner.soundex(owner.getLastName());
709	        String identityKey = owner.getIdentityKey();
710	        return this.clinicService.findAllOwners().stream()
711	            .filter(existing -> existing.getId() != null
712	                && !existing.isDeleted()
713	                && Owner.soundex(existing.getLastName()).equals(lastNameSoundex)
714	                && owner.getPostcode().equals(existing.getPostcode())
715	                && !identityKey.equals(existing.getIdentityKey()))
716	            .map(Owner::getId)
717	            .min(Integer::compareTo)
718	            .orElse(null);
719	    }
