824	    /**
825	     * The fixed public holidays that the business-day roll skips. A registration date landing on
826	     * any of these is rolled forward, exactly as it is for a weekend.
827	     */
828	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
829	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
830	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
