853	    private static boolean isNonBusinessDay(LocalDate date) {
854	        DayOfWeek dayOfWeek = date.getDayOfWeek();
855	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY
856	            || PUBLIC_HOLIDAYS.contains(date);
857	    }
