889	    /**
890	     * Computes the membership level to assign to the owner being created, applying the household
891	     * level ceiling: a new owner's level may not exceed one above the current maximum membership
892	     * level among their existing household members. The owner's own naturally derived level (see
893	     * {@link Owner#getComputedMembershipLevel()}) is returned unchanged when there is no existing
894	     * household member; otherwise it is capped at {@code maxHouseholdLevel + 1}. Existing members are
895	     * the non-deleted owners already sharing the owner's {@code householdId}; the owner being created
896	     * is not yet persisted, so it is naturally excluded.
897	     *
898	     * @param owner the owner being created, with {@code householdId} and the fields driving its
899	     *              membership level already set
900	     * @return the (possibly capped) membership level to store on the owner
901	     */
902	    private int cappedMembershipLevel(Owner owner) {
903	        int naturalLevel = owner.getComputedMembershipLevel();
904	        String householdId = owner.getHouseholdId();
905	        if (householdId == null) {
906	            return naturalLevel;
907	        }
908	        java.util.OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
909	            .filter(existing -> existing.getId() != null
910	                && !existing.isDeleted()
911	                && householdId.equals(existing.getHouseholdId()))
912	            .mapToInt(Owner::getMembershipLevel)
913	            .max();
914	        if (maxHouseholdLevel.isEmpty()) {
915	            return naturalLevel;
916	        }
917	        return Math.min(naturalLevel, maxHouseholdLevel.getAsInt() + 1);
918	    }
