920	    /**
921	     * Derives the stable household identifier for a given last name and postcode. The value is the
922	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
923	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
924	     * normalized last name and postcode — they belong to the same household automatically.
925	     *
926	     * @param lastName the last name of the household
927	     * @param postcode the postcode of the household (may be {@code null})
928	     * @return the deterministic household identifier
929	     */
930	    private static String householdIdFor(String lastName, String postcode) {
931	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
932	        try {
933	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
934	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
935	            StringBuilder sb = new StringBuilder(digest.length * 2);
936	            for (byte b : digest) {
937	                sb.append(String.format("%02x", b));
938	            }
939	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
940	        }
941	        catch (java.security.NoSuchAlgorithmException e) {
942	            throw new IllegalStateException("SHA-256 not available", e);
943	        }
944	    }
945	
946	    /**
947	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
948	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
949	     * single space, and the result is lower-cased.
950	     *
951	     * @param value the raw field value
952	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
953	     */
954	    private static String normalizeIdentity(String value) {
955	        if (value == null) {
956	            return "";
957	        }
