89	    @Column(name = "possible_duplicate")
90	    private Boolean possibleDuplicate;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted", nullable = false)
96	    private boolean deleted = false;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    /**
110	     * The owner's salutation, derived from the {@link #title} and last name: {@code title + ' ' +
111	     * lastName} when a title is present, or just the last name when no title was supplied.
112	     */
113	    @Transient
114	    public String getSalutation() {
115	        if (this.title == null || this.title.isBlank()) {
116	            return getLastName();
117	        }
118	        return this.title + " " + getLastName();
119	    }
