150	        this.city = city;
151	    }
152	
153	    public String getTelephone() {
154	        return this.telephone;
155	    }
156	
157	    public void setTelephone(String telephone) {
158	        this.telephone = telephone;
159	    }
160	
161	    public String getEmail() {
162	        return this.email;
163	    }
164	
165	    /**
166	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
167	     * {@code null} value (email omitted) is preserved as {@code null}.
168	     */
169	    public void setEmail(String email) {
170	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public LocalDate getBirthDate() {
182	        return this.birthDate;
183	    }
184	
185	    public void setBirthDate(LocalDate birthDate) {
186	        this.birthDate = birthDate;
187	    }
188	
189	    /**
190	     * The owner's age band, derived from {@link #birthDate} measured against the
191	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
192	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
193	     * supplied, so the field is simply absent from the response.
194	     */
195	    @Transient
196	    public String getAgeBand() {
197	        if (this.birthDate == null) {
198	            return null;
199	        }
200	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
201	        int age = java.time.Period.between(this.birthDate, reference).getYears();
202	        if (age < 18) {
203	            return "MINOR";
204	        }
205	        if (age < 65) {
206	            return "ADULT";
207	        }
208	        return "SENIOR";
209	    }
210	
211	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
212	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
213	
214	    /**
215	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
216	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
217	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
218	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
219	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
220	     */
221	    @Transient
222	    public String getTelephoneDisplay() {
223	        if (this.telephone == null || !this.telephone.startsWith("+")) {
224	            return this.telephone;
225	        }
226	        String digits = this.telephone.substring(1);
227	        if (!digits.matches("[0-9]+")) {
228	            return this.telephone;
229	        }
230	        String countryCode = null;
231	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
232	            if (digits.startsWith(entry.getKey())
233	                && digits.length() - entry.getKey().length() == entry.getValue()) {
234	                countryCode = entry.getKey();
235	                break;
236	            }
237	        }
238	        if (countryCode == null) {
239	            return this.telephone;
240	        }
241	        String national = digits.substring(countryCode.length());
242	        StringBuilder grouped = new StringBuilder();
243	        for (int i = 0; i < national.length(); i += 3) {
244	            if (grouped.length() > 0) {
245	                grouped.append(' ');
246	            }
247	            grouped.append(national, i, Math.min(i + 3, national.length()));
248	        }
249	        return "+" + countryCode + " " + grouped;
250	    }
251	
252	    public String getMemberId() {
253	        return this.memberId;
254	    }
255	
256	    public void setMemberId(String memberId) {
257	        this.memberId = memberId;
258	    }
259	
260	    /** The month on which the fiscal year starts: 1 July. */
261	    private static final java.time.Month FISCAL_YEAR_START_MONTH = java.time.Month.JULY;
262	
263	    /**
264	     * The calendar year in which the fiscal year containing {@code date} began. The fiscal year
265	     * starts on 1 July, so a date in July through December belongs to a fiscal year that began in
266	     * its own calendar year, while a date in January through June belongs to one that began in the
267	     * previous calendar year.
268	     */
269	    private static int fiscalYearStart(LocalDate date) {
270	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
271	    }
272	
273	    /**
274	     * The owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the two-digit fiscal-year
275	     * (FY) segment carried inside the {@link #memberId} (e.g. a {@code memberId} of
276	     * {@code NSW261A2B3C4D5} yields {@code FY26}). The FY segment sits immediately after the region
277	     * prefix and before the 8-hex {@code HASH8} and single check digit, so it is read back off the
278	     * member id (ignoring any {@code -<n>} collision suffix). {@code null} until a member id is
279	     * assigned.
280	     */
281	    @Transient
282	    public String getFiscalYear() {
283	        String base = memberIdBase();
284	        if (base == null || base.length() < 11) {
285	            return null;
286	        }
287	        return "FY" + base.substring(base.length() - 11, base.length() - 9);
288	    }
289	
290	    /**
291	     * The {@link #memberId} with any {@code -<n>} collision suffix stripped, i.e. the
292	     * {@code <REGION><FY><HASH8><CHK>} core from which the region and fiscal-year segments are read
293	     * back. {@code null} when no member id is assigned.
294	     */
295	    private String memberIdBase() {
296	        if (this.memberId == null) {
297	            return null;
298	        }
299	        int dash = this.memberId.indexOf('-');
300	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
301	    }
302	
303	    /**
304	     * The owner's membership points, derived from the owner's own fields. Points start at 0 and
305	     * accumulate: 2 when an email is present, 1 when the owner has no namesakes ({@code namesakeCount}
306	     * is 0), 2 when the owner belongs to a household of 3 or more members ({@code householdSize} is at
307	     * least 3), and 3 when the owner's tenure — the number of elapsed fiscal years from
308	     * {@link #registrationDate} to today, the fiscal year starting on 1 July — exceeds one. Because
309	     * a newly created owner registers in the current fiscal year and so has zero tenure, and joins a
310	     * household of at most itself unless others already share it, a new owner's points reflect only the
311	     * factors captured at creation time.
312	     */
313	    @Transient
314	    public Integer getMembershipPoints() {
315	        int points = 0;
316	        boolean hasEmail = this.email != null && !this.email.isBlank();
317	        if (hasEmail) {
318	            points += 2;
319	        }
320	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
321	        if (noNamesakes) {
322	            points += 1;
323	        }
324	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
325	        if (largeHousehold) {
326	            points += 2;
327	        }
328	        boolean longTenure = this.registrationDate != null
329	            && (fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate)) > 1;
330	        if (longTenure) {
331	            points += 3;
332	        }
333	        return points;
334	    }
335	
336	    /**
337	     * The owner's membership level, a number from 1 to 4. Ordinarily it is the level derived from
338	     * {@link #getMembershipPoints()} (level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
339	     * points, and level 4 for 6 or more points). When an explicit level has been assigned at creation
340	     * time — because it was capped to at most one above the maximum level among the owner's existing
341	     * household members — that stored value is returned instead.
342	     */
343	    public Integer getMembershipLevel() {
344	        if (this.membershipLevel != null) {
345	            return this.membershipLevel;
346	        }
347	        return getComputedMembershipLevel();
348	    }
349	
350	    public void setMembershipLevel(Integer membershipLevel) {
351	        this.membershipLevel = membershipLevel;
352	    }
353	
354	    /**
355	     * The membership level derived purely from {@link #getMembershipPoints()} (before any
356	     * household level ceiling is applied): level 1 for 0-1 points, level 2 for 2-3 points, level 3
357	     * for 4-5 points, and level 4 for 6 or more points.
358	     */
359	    @Transient
360	    public Integer getComputedMembershipLevel() {
361	        int points = getMembershipPoints();
362	        if (points <= 1) {
363	            return 1;
364	        }
365	        if (points <= 3) {
366	            return 2;
367	        }
368	        if (points <= 5) {
369	            return 3;
370	        }
371	        return 4;
372	    }
373	
374	    /** City -> canonical region for the {@code region} derivation. */
375	    private static final Map<String, String> CITY_REGION = Map.of(
376	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
377	
378	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
379	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
380	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
381	
382	    /** Region -> IANA timezone for the {@code timezone} derivation. */
383	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
384	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
385	
386	    /**
387	     * The region code that forms the {@code REGION} segment of the {@link #memberId}, derived
388	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
389	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
390	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
391	     * {@code UNKNOWN} when neither source resolves a region.
392	     */
393	    @Transient
394	    public String getRegion() {
395	        String region = regionForPostcode(this.postcode);
396	        if (region != null) {
397	            return region;
398	        }
399	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
400	    }
401	
402	    /**
403	     * The owner's locality: the {@code REGION} segment of its {@link #memberId} (its leading region
404	     * prefix). Because the member id is {@code <REGION><FY><HASH8><CHK>} with {@code REGION} derived
405	     * from the postcode, and the {@code FY} (2), {@code HASH8} (8) and {@code CHK} (1) tail is a fixed
406	     * 11 characters, the locality reads that region back off the identity (ignoring any {@code -<n>}
407	     * collision suffix). Returns {@code UNKNOWN} until a member id is assigned.
408	     */
409	    @Transient
410	    public String getLocality() {
411	        String base = memberIdBase();
412	        if (base == null) {
413	            return "UNKNOWN";
414	        }
415	        return base.length() > 11 ? base.substring(0, base.length() - 11) : base;
416	    }
417	
418	    /**
419	     * The owner's timezone as an IANA name, derived from its {@link #getLocality() locality} (the
420	     * region) via the fixed region-to-timezone table: {@code NSW->Australia/Sydney},
421	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}. Returns {@code null} when
422	     * the locality is not one of those regions.
423	     */
424	    @Transient
425	    public String getTimezone() {
426	        return REGION_TIMEZONE.get(getLocality());
427	    }
428	
429	    /**
430	     * The owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM} when
431	     * {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise {@code STANDARD}.
432	     * {@code AREA} is {@code METRO} when the {@link #getLocality() locality} is a known region
433	     * (NSW, VIC or QLD), otherwise {@code REGIONAL}. Thus one of {@code PREMIUM_METRO},
434	     * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
435	     */
436	    @Transient
437	    public String getOwnerSegment() {
438	        Integer level = getMembershipLevel();
439	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
440	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
441	        return tier + "_" + area;
442	    }
443	
444	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
445	    private static String regionForPostcode(String postcode) {
446	        if (postcode == null) {
447	            return null;
448	        }
449	        int value;
450	        try {
451	            value = Integer.parseInt(postcode.trim());
452	        }
453	        catch (NumberFormatException ex) {
454	            return null;
455	        }
456	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
457	            int[] range = entry.getValue();
458	            if (value >= range[0] && value <= range[1]) {
459	                return entry.getKey();
460	            }
461	        }
462	        return null;
463	    }
464	
465	    /**
466	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
467	     * the full lower-case hex SHA-256 digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
468	     * soundex(lastName)}, where the telephone is the stored E.164 value, the email is the stored
469	     * lower-cased value (empty when absent) and the last-name segment is the American Soundex code of
470	     * the last name. Two owners are duplicates only when their whole identity keys are equal, so
471	     * owners sharing a last name (by soundex) and postcode but carrying different telephones no longer
472	     * collide here — they are surfaced as a soft (possible) duplicate instead.
473	     */
474	    @Transient
475	    public String getIdentityKey() {
476	        String telephonePart = this.telephone == null ? "" : this.telephone;
477	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
478	        String key = telephonePart + "|" + emailPart + "|" + soundex(getLastName());
479	        return sha256Hex(key);
480	    }
481	
482	    /**
483	     * The American Soundex code of {@code name}: the first letter followed by three digits (padded
484	     * with {@code '0'} when there are too few coded consonants, truncated to four characters
485	     * otherwise). Non-letters are ignored; a {@code null}, blank, or letter-free value yields the
486	     * empty string. Consonants are grouped b/f/p/v=1, c/g/j/k/q/s/x/z=2, d/t=3, l=4, m/n=5, r=6;
487	     * adjacent same-coded letters (and same-coded letters separated only by {@code h}/{@code w}) are
488	     * coded once, while a vowel between them causes both to be coded.
489	     */
490	    public static String soundex(String name) {
491	        if (name == null) {
492	            return "";
493	        }
494	        StringBuilder letters = new StringBuilder();
495	        for (char c : name.toUpperCase(Locale.ROOT).toCharArray()) {
496	            if (c >= 'A' && c <= 'Z') {
497	                letters.append(c);
498	            }
499	        }
500	        if (letters.length() == 0) {
501	            return "";
502	        }
503	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
504	        char prevCode = soundexCode(letters.charAt(0));
505	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
506	            char c = letters.charAt(i);
507	            if (c == 'H' || c == 'W') {
508	                // Acts as a connector: same-coded consonants either side stay adjacent.
509	                continue;
510	            }
511	            if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') {
512	                // A vowel separates same-coded consonants, so both are coded.
513	                prevCode = '0';
514	                continue;
515	            }
516	            char digit = soundexCode(c);
517	            if (digit != '0' && digit != prevCode) {
518	                code.append(digit);
519	            }
520	            prevCode = digit;
521	        }
522	        while (code.length() < 4) {
523	            code.append('0');
524	        }
525	        return code.toString();
526	    }
527	
528	    private static char soundexCode(char c) {
529	        switch (c) {
530	            case 'B': case 'F': case 'P': case 'V':
531	                return '1';
532	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
533	                return '2';
534	            case 'D': case 'T':
535	                return '3';
536	            case 'L':
537	                return '4';
538	            case 'M': case 'N':
539	                return '5';
540	            case 'R':
541	                return '6';
542	            default:
543	                return '0';
544	        }
545	    }
546	
547	    /** The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
548	    private static String sha256Hex(String value) {
549	        try {
550	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
551	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
552	            StringBuilder sb = new StringBuilder(digest.length * 2);
553	            for (byte b : digest) {
554	                sb.append(String.format("%02x", b));
555	            }
556	            return sb.toString();
557	        }
558	        catch (java.security.NoSuchAlgorithmException e) {
559	            throw new IllegalStateException("SHA-256 not available", e);
560	        }
561	    }
562	
563	    public String getHouseholdId() {
564	        return this.householdId;
565	    }
566	
567	    public void setHouseholdId(String householdId) {
568	        this.householdId = householdId;
569	    }
570	
571	    public Integer getNamesakeCount() {
572	        return this.namesakeCount;
573	    }
574	
575	    public void setNamesakeCount(Integer namesakeCount) {
576	        this.namesakeCount = namesakeCount;
577	    }
578	
579	    public Integer getHouseholdSize() {
580	        return this.householdSize;
581	    }
582	
583	    public void setHouseholdSize(Integer householdSize) {
584	        this.householdSize = householdSize;
585	    }
586	
587	    public String getPostcode() {
588	        return this.postcode;
589	    }
590	
591	    public void setPostcode(String postcode) {
592	        this.postcode = postcode;
593	    }
594	
595	    public Boolean getPossibleDuplicate() {
596	        return this.possibleDuplicate;
597	    }
598	
599	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
600	        this.possibleDuplicate = possibleDuplicate;
601	    }
602	
603	    public Integer getPossibleDuplicateOf() {
604	        return this.possibleDuplicateOf;
605	    }
606	
607	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
608	        this.possibleDuplicateOf = possibleDuplicateOf;
609	    }
610	
611	    /**
612	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
613	     * {@code DELETE /api/owners/{id}} marks the owner deleted (setting this true) while retaining the
614	     * row, and duplicate/identity detection ignores owners flagged deleted.
615	     */
616	    public boolean isDeleted() {
617	        return this.deleted;
618	    }
619	
620	    public void setDeleted(boolean deleted) {
621	        this.deleted = deleted;
622	    }
623	
624	    protected Set<Pet> getPetsInternal() {
625	        if (this.pets == null) {
626	            this.pets = new HashSet<>();
627	        }
628	        return this.pets;
629	    }
630	
631	    protected void setPetsInternal(Set<Pet> pets) {
632	        this.pets = pets;
633	    }
634	
635	    public List<Pet> getPets() {
636	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
637	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
638	        return Collections.unmodifiableList(sortedPets);
639	    }
640	
641	    public void setPets(List<Pet> pets) {
642	        this.pets = new HashSet<>(pets);
643	    }
644	
645	    public void addPet(Pet pet) {
646	        getPetsInternal().add(pet);
647	        pet.setOwner(this);
648	    }
649	
650	    /**
651	     * Return the Pet with the given name, or null if none found for this Owner.
652	     *
653	     * @param name to test
654	     * @return true if pet name is already in use
655	     */
656	    public Pet getPet(String name) {
657	        return getPet(name, false);
658	    }
659	
660	    /**
661	     * Return the Pet with the given name, or null if none found for this Owner.
662	     *
663	     * @param name to test
664	     * @return true if pet name is already in use
665	     */
666	    public Pet getPet(String name, boolean ignoreNew) {
667	        name = name.toLowerCase();
668	        for (Pet pet : getPetsInternal()) {
669	            if (!ignoreNew || !pet.isNew()) {
670	                String compName = pet.getName();
671	                compName = compName.toLowerCase();
672	                if (compName.equals(name)) {
673	                    return pet;
674	                }
675	            }
676	        }
677	        return null;
678	    }
679	
680	    public Pet getPet(Integer petId) {
681	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
682	    }
683	
684	    @Override
685	    public String toString() {
686	        return new ToStringCreator(this)
687	
688	            .append("id", this.getId())
689	            .append("new", this.isNew())
690	            .append("lastName", this.getLastName())
691	            .append("firstName", this.getFirstName())
692	            .append("address", this.address)
693	            .append("city", this.city)
694	            .append("telephone", this.telephone)
695	            .append("email", this.email)
696	            .toString();
697	    }
698	}
