private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
    "mailinator.com", "tempmail.com", "guerrillamail.com");

/**
 * The provider (second-level) labels of the disposable blocklist domains ({@code mailinator},
 * {@code tempmail}, {@code guerrillamail}), used to recognise domains that are
 * <em>disposable-adjacent</em>: not on the exact blocklist (so accepted at create) but clearly a
 * variant of a known disposable provider. Derived from {@link #DISPOSABLE_EMAIL_DOMAINS} so the
 * two stay in sync.
 */
private static final java.util.Set<String> DISPOSABLE_PROVIDER_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
    .map(OwnerRestControllerV1::secondLevelLabel)
    .filter(java.util.Objects::nonNull)
    .collect(java.util.stream.Collectors.toUnmodifiableSet());

/**
 * The second-level label of a dotted domain, i.e. the label immediately preceding the top-level
 * label ({@code mailinator.com -> mailinator}, {@code sub.tempmail.net -> tempmail}). Returns
 * {@code null} for a {@code null}, blank, or single-label value that has no second level.
 *
 * @param domain the (already lower-cased) domain
 * @return the second-level label, or {@code null} when there is none
 */
private static String secondLevelLabel(String domain) {
    if (isBlank(domain)) {
        return null;
    }
    String[] labels = domain.split("\\.");
    return labels.length < 2 ? null : labels[labels.length - 2];
}

/**
 * Determines whether an email's domain is <em>disposable-adjacent</em>: a domain that is not
 * itself on the {@link #DISPOSABLE_EMAIL_DOMAINS disposable blocklist} (those are rejected
 * outright at create) but is nonetheless a variant of a known disposable provider — a subdomain
 * of a blocklisted domain, or a domain sharing a blocklisted provider's second-level label under
 * a different top-level domain (e.g. {@code mailinator.net} or {@code sub.tempmail.com}). Email is
 * optional; a {@code null}, blank, or {@code '@'}-less value is not adjacent. The domain is
 * compared case-insensitively.
 *
 * @param email the owner's email (may be {@code null})
 * @return {@code true} if the email's domain is disposable-adjacent
 */
private static boolean isDisposableAdjacent(String email) {
    if (isBlank(email)) {
        return false;
    }
    int at = email.lastIndexOf('@');
    if (at < 0) {
        return false;
    }
    String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
    if (domain.isEmpty() || DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
        return false;
    }
    String providerLabel = secondLevelLabel(domain);
    return providerLabel != null && DISPOSABLE_PROVIDER_LABELS.contains(providerLabel);
}

/**
 * Determines whether an owner warrants a {@code riskFlag}: true when any of the following hold —
 * the owner is a possible (soft) duplicate, its email domain is
 * {@link #isDisposableAdjacent(String) disposable-adjacent}, or its city is over its soft capacity
 * (the {@link #isCityApproachingCapacity(String) soft-capacity} threshold that raises
 * {@code capacityWarning}); otherwise false.
 *
 * @param possibleDuplicate whether the owner is flagged a possible duplicate
 * @param email the owner's email (may be {@code null})
 * @param city the owner's city
 * @return {@code true} if the owner should be risk-flagged
 */
private boolean computeRiskFlag(Boolean possibleDuplicate, String email, String city) {
    return Boolean.TRUE.equals(possibleDuplicate)
        || isDisposableAdjacent(email)
        || isCityApproachingCapacity(city);
}

